import { t } from './i18n.mjs';
import {cardEscape as e} from './debt-card.mjs';
const shapes={home:'<path d="m3 11 9-8 9 8v10h-6v-7H9v7H3Z"/>',discover:'<circle cx="12" cy="12" r="10"/><path d="m16 8-3 5-5 3 3-5Z"/>',community:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a3 3 0 0 1 0 6M22 21v-3a6 6 0 0 0-4-6"/>',debts:'<path d="m2 7 10-5 10 5-10 5Zm0 5 10 5 10-5M2 17l10 5 10-5"/>',messages:'<path d="M21 11a9 9 0 0 1-9 9H5l-4 3 2-7a9 9 0 1 1 18-5Z"/>',notifications:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5l-2 3Zm5 3a2 2 0 0 0 4 0"/>',gesture:'<path d="M8 12V5a1.5 1.5 0 0 1 3 0v6-2a1.5 1.5 0 0 1 3 0v2-1a1.5 1.5 0 0 1 3 0v2a1.5 1.5 0 0 1 3 0v4a5 5 0 0 1-5 5h-2a5 5 0 0 1-4-2l-4-5a1.6 1.6 0 0 1 2-2l1 1"/>',heart:'<path d="M12 21C-8 9 5-4 12 5c7-9 20 4 0 16Z"/>',book:'<path d="M12 5v17M2 3c4-1 7 0 10 2 3-2 6-3 10-2v16c-4-1-7 0-10 2-3-2-6-3-10-2Z"/>',impact:'<path d="M4 20V12M10 20V7M16 20V3M22 20V1"/>',shield:'<path d="m12 2 9 4v6c0 5-5 8-9 10-4-2-9-5-9-10V6Zm-4 9 3 3 5-6"/>',saved:'<path d="m12 2 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/>'};
export const di=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.heart}</svg>`;
export function discoverIntro(){return `<section class="discover-intro"><span class="discover-eyebrow">${t("DISCOVER & SUPPORT","KHÁM PHÁ &amp; HỖ TRỢ","둘러보고 돕기")}</span><h1>${t("Real People,","Người thật,","실제 사람,")}<br>${t("Real Stories","Chuyện thật","실제 이야기")}</h1><div class="discover-underline"></div><p class="discover-lead">${t("Discover real debt journeys, hear their stories, and lend a helping hand.","Khám phá hành trình trả nợ, lắng nghe câu chuyện và giúp ai đó tiến gần hơn đến mục tiêu thoát nợ.","채무를 갚아가는 사람들의 이야기를 듣고 빚에서 벗어나는 여정에 힘을 보태세요.")}</p><div class="discover-values">${[['heart',t("Support with Purpose","Giúp đỡ có ý nghĩa","뜻깊은 도움"),t("A little support can spark a fresh start.","Một chút đồng hành, một khởi đầu mới.","작은 도움이 새로운 시작을 만듭니다.")],['book',t("Stories that Inspire","Những câu chuyện truyền cảm hứng","힘이 되는 이야기"),t("Hear the story behind each debt.","Lắng nghe câu chuyện phía sau mỗi khoản nợ.","각 채무에 담긴 이야기를 들어보세요.")],['community',t("A Caring Community","Cộng đồng sẻ chia","서로 돌보는 공동체"),t("Let's build a caring community together.","Cùng nhau xây dựng một cộng đồng tử tế.","서로 돌보는 공동체를 함께 만들어가요.")]].map(([icon,title,copy])=>`<div><span>${di(icon)}</span><div><h2>${title}</h2><p>${copy}</p></div></div>`).join('')}</div><div class="discover-landscape"><div class="discover-land-sun"></div><div class="discover-land-hill"></div><div class="discover-land-hill second"></div><span>${t("Every small kindness","Mỗi việc tử tế nhỏ","작은 친절 하나가")}<br>${t("opens a new path.","mở ra một lối đi mới.","새로운 길을 엽니다.")}</span></div></section>`;}
export function discoverCommunity({stories,saved}){return `<section class="discover-community"><section class="discover-panel"><div class="discover-panel-title"><span>${di('impact')}</span><div><h2>${t("Our Community Impact","Dấu ấn cộng đồng","우리 공동체가 만드는 변화")}</h2><p>${t("Small steps. Shared hope.","Bước nhỏ. Hy vọng chung.","작은 걸음, 함께 품는 희망.")}</p></div></div><div class="discover-stat"><span>${di('community')}</span><div><strong>${stories}</strong><p>${t("Stories in the preview","Câu chuyện trong bản thử","미리보기 이야기")}</p></div></div><div class="discover-stat"><span>${di('saved')}</span><div><strong>${saved}</strong><p>${t("Cards you saved","Thẻ bạn đã lưu","저장한 카드")}</p></div></div><div class="discover-stat"><span>${di('shield')}</span><div><strong>${t("Coming soon","Sắp ra mắt","준비 중")}</strong><p>${t("Profile verification and payments","Xác minh hồ sơ và thanh toán","프로필 인증 및 결제")}</p></div></div></section><section class="discover-quote discover-panel"><span>“</span><blockquote>${t("A little help doesn't just change a day.","Một chút giúp đỡ không chỉ làm thay đổi một ngày.","작은 도움이 하루를 바꾸고")} ${t("It can open a whole new chapter.","Nó có thể mở ra cả một chương mới.","완전히 새로운 시작을 열어줄 수 있습니다.")}</blockquote><div><img src="assets/debtfreelately-mark-clean.png" alt=""><p>DebtFreeLately</p></div></section></section>`;}
import {categoryLabel} from './story-categories.mjs';

export function discoverSwipeHint() {
  return `<p class="discover-swipe-hint"><span aria-hidden="true">← ${di('gesture')} →</span>${t('Swipe to discover more stories', 'Vuốt để khám phá thêm câu chuyện', '밀어서 더 많은 이야기를 둘러보세요')}</p>`;
}

export function discoveryCard(card,{post,saved}){const photo=card.photo;return `<article class="discovery-debt-card"><div class="discovery-photo ${photo?'portrait':'landscape'}"><img src="${e(photo||'assets/journey-mountains.png')}" alt="${photo?t("Profile picture of ","Ảnh đại diện của ","프로필 사진: ")+e(card.name):t("Illustrated landscape","Phong cảnh minh họa","풍경 일러스트")}"><span class="discovery-category">${di('book')}${e(categoryLabel(post.category))}</span><span class="discovery-verified">${di('shield')}${post.sample?t("Sample profile","Hồ sơ mẫu","예시 프로필"):post.approved?t("Approved","Đã duyệt","승인됨"):t("Unverified","Chưa xác minh","미인증")}</span></div><div class="discovery-card-body"><div class="discovery-person">${photo?`<img src="${e(photo)}" alt="">`:''}<div><h2>${e(card.name)}${card.age?`, ${e(card.age)}`:''}</h2>${card.location?`<p><span aria-hidden="true">⌖</span> ${e(card.location)}</p>`:''}</div></div><div class="discovery-debts">${card.debts.map(d=>`<section class="discovery-debt"><h3 class="discovery-title">${e(d.title)} <span aria-hidden="true">🌱</span></h3>${Number.isSafeInteger(d.amount)?`<p class="discovery-debt-amount">${new Intl.NumberFormat(t("en-US","vi-VN","ko-KR")).format(d.amount)} ₫</p>`:''}${d.story?`<p class="discovery-story">${e(d.story)}</p>`:''}</section>`).join('')}</div><div class="discovery-card-facts"><div>${di('debts')}<p>${t("Debt","Khoản nợ","채무")}<strong>${e(categoryLabel(post.category))}</strong></p></div><button class="discovery-read" type="button" data-dc="read" data-id="${e(post.id)}">${t("Details","Chi tiết","상세 보기")}</button></div><div class="discovery-card-actions"><button data-dc="skip" data-id="${e(post.id)}" aria-label="${t("Skip card","Bỏ qua thẻ","카드 건너뛰기")}"><span>×</span> ${t("Skip","Bỏ qua","건너뛰기")}</button><button data-dc="save" data-id="${e(post.id)}" aria-label="${saved?t("Unsave card","Bỏ lưu thẻ","카드 저장 취소"):t("Save card","Lưu thẻ","카드 저장")}" aria-pressed="${saved}">${di('saved')}${saved?t("Saved","Đã lưu","저장됨"):t("Save","Lưu","저장")}</button><button data-dc="detail" data-id="${e(post.id)}" aria-label="${t("View card details","Xem thêm thông tin chi tiết","카드 상세 보기")}"><img src="assets/debtfreelately-mark-clean.png" alt=""> ${t("Support","Hỗ trợ","돕기")}</button></div></div></article>`;}

